(function(){
    const results = { passed: 0, failed: 0, errors: [], warnings: [] };
    function pass(msg) { console.log('✅ ' + msg); results.passed++; }
    function fail(msg) { console.error('❌ ' + msg); results.failed++; results.errors.push(msg); }
    function warn(msg) { console.warn('⚠️ ' + msg); results.warnings.push(msg); }

    console.log('========================================');
    console.log('  星愿花园 v6.4 浏览器完整验证');
    console.log('========================================');

    
    console.log('\n--- P0: 页面加载 ---');
    try {
        if (document.title.includes('星愿') || document.title.includes('花园')) pass('页面标题: ' + document.title);
        else warn('页面标题: ' + document.title + ' (未包含"星愿花园")');

        const sk = document.getElementById('skeleton-screen');
        if (!sk || sk.classList.contains('hidden') || getComputedStyle(sk).display === 'none') pass('骨架屏已隐藏');
        else fail('骨架屏未隐藏');

        const island = document.getElementById('page-island');
        if (island) {
            const cs = getComputedStyle(island);
            if (cs.display !== 'none') pass('island 主界面可见');
            else pass('island 页面存在');
        } else fail('page-island 不存在');
    } catch(e) { fail('P0异常: ' + e.message); }

    
    console.log('\n--- P1: 核心状态对象 ---');
    try {
        if (typeof state !== 'undefined') pass('state 对象存在');
        else fail('state 对象未定义');

        if (typeof DEFAULT_STATE !== 'undefined') pass('DEFAULT_STATE 存在');
        else fail('DEFAULT_STATE 未定义');

        const arrayProps = ['wishes','diaries','emotionHistory','badges','unlockedPersonas',
            'testHistory','courseProgress','topBeliefs','moodHistory','cbtRecords','revisionNotes',
            'satsRecords','habits','myTasks','universeTasks','items','rampages','signs','wheels',
            'history','bookmarks','bookNotes','favMovies','movieLinks','cards','planNotes','completedChallenges'];
        for (const p of arrayProps) {
            if (typeof state !== 'undefined' && Array.isArray(state[p])) pass('state.' + p + ' 是数组');
            else fail('state.' + p + ' 缺失或不是数组');
        }

        const objProps = ['plans','garden','purify','mentalDiet','affirmations'];
        for (const p of objProps) {
            if (typeof state !== 'undefined' && typeof state[p] === 'object' && state[p] !== null) pass('state.' + p + ' 是对象');
            else fail('state.' + p + ' 缺失或不是对象');
        }
    } catch(e) { fail('P1异常: ' + e.message); }

    
    console.log('\n--- P2: 核心函数存在性 ---');
    const criticalFns = [
        'init','showPage','goBack','goHome','switchTab','openModule','loadState','saveState',
        'createFireflies','updateTopbar','updateGreeting','updateMoodDisplay','updateNavActive',
        'showModal','hideModal','showToast','triggerConfetti','playSound','speak','showVoiceBubble',
        'startTest','renderTestQ','selectTestOpt','nextTestQ','drawTarot','startTutorial',
        'nextTutorialStep','skipTutorial','finishTutorial','startWelcomeTest','enterIslandFromTest',
        'addVipNavEntry','addVipToMePage','updateHomeStats','checkDailyReset','checkReminders',
        'updateTimeAndWeather','updateFortuneCard','renderSmartRecommendations','renderHeatmap',
        'getSmartRecommendations','getUnlockedBadges','getBadgeProgress','checkNewBadges','renderBadgeWall',
        'renderSearchResults','onSearchInput','initSearch','renderAudioScenes','startAudioScene',
        'updateSatsTimerDisplay','startSatsTimer','pauseSatsTimer','resetSatsTimer','onEmotionSlide',
        'saveEmotionNote','selectTarotSpread','selectTarotCat','renderTarot','updateNickname',
        'toggleDarkMode','showFeedbackModal','openCrystalPage','openAffirmCollection','openCardCollection',
        'openBadgeWall','openSearch','initReports','renderMonthlyReport','renderYearlySummary',
        'loadReportData','renderCommunityFeed','renderVoiceRecordings','stopSleepStory',
        'startBreathe','stopBreathe','loadAiHistory','renderAiChat','loadStories','renderStories',
        'renderMovies','initVip','initEmotion','initSp','initWealth','initMovies','initAi',
        'initDreams','initStories','initSats','initBackup','initAudioPage','initBootcamp',
        'initBreathe','initVoice','initSleep','initHealth','initStats','initCleanup','initAbout',
        'renderDataOverview','exportData','importAllData','logDiet','openMentalDiet','createFireflies',
        'updateTopbar','updateGreeting','updateMoodDisplay','updateNavActive','getTodayStr',
        'showVoiceBubble','getDailyFortune','recalcHabitStreak','getLevel',
        'addWishProgress','newDiaryPrompt','recordMood','addPlacematTask','addHabit',
        'closePage','addWish','addDiary','logEmotion','addTask','renderBreathe','importData',
        'renderFortune','checkStreak','updateStreak','checkLevel','updateLevel','checkMastery','updateMastery'
    ];

    for (const fn of criticalFns) {
        if (typeof window[fn] === 'function') pass('函数: ' + fn);
        else fail('函数缺失: ' + fn);
    }

    
    console.log('\n--- P3: 导航页面切换 ---');
    const tabs = ['island', 'tools', 'library', 'journal', 'me'];
    for (const tab of tabs) {
        try {
            switchTab(tab);
            const pageId = 'page-' + (tab === 'island' ? 'island' : tab === 'tools' ? 'tools' : tab === 'library' ? 'library' : tab === 'journal' ? 'journal' : 'me');
            const page = document.getElementById(pageId);
            if (page && page.classList.contains('active')) pass('switchTab("' + tab + '") 激活');
            else fail('switchTab("' + tab + '") 未激活 ' + pageId);
        } catch(e) { fail('switchTab("' + tab + '") 异常: ' + e.message); }
    }

    
    console.log('\n--- P4: showPage 所有目标页面 ---');
    const pageTargets = ['welcome','island','me','tools','library','journal','vip','search',
        'reports','community','shop','coach','emotion','sp','wealth','movies','ai','dreams',
        'stories','sats','backup','vip-plans','audio','bootcamp','breathe','voice',
        'sleep','health','stats','cleanup','about','temple','tower','stars','cloud',
        'garden','diary','wishwall','sky','growth','tarot','plans','timer','challenge',
        'mood-chart','habit-calendar','placemat','remember','creationbox','rampage','vision',
        'qr-sync','badge-wall','privacy','369','55x5','signs','wheel','68sec','prosperity',
        'pillow','treasurebox','timeline','manifest-report','affirm-loop'];
    for (const name of pageTargets) {
        try {
            showPage(name);
            const p = document.getElementById('page-' + name);
            if (p && p.classList.contains('active')) pass('showPage("' + name + '") 激活');
            else if (p) warn('showPage("' + name + '") 未激活（可能未激活class）');
            else fail('showPage("' + name + '") page-' + name + ' 不存在');
        } catch(e) { fail('showPage("' + name + '") 异常: ' + e.message); }
    }

    
    console.log('\n--- P5: 核心交互功能 ---');
    try {
        showPage('wishwall');
        const wBefore = state.wishes.length;
        addWishProgress(0);
        if (state.wishes.length > wBefore || state.wishes[wBefore]) pass('addWishProgress() 成功');
        else warn('addWishProgress() 可能未添加（检查状态）');
    } catch(e) { fail('addWishProgress() 异常: ' + e.message); }

    try {
        showPage('habit-calendar');
        const hInput = document.getElementById('habit-name-input');
        if (hInput) hInput.value = '测试习惯';
        const hBefore = state.habits.length;
        addHabit();
        if (state.habits.length > hBefore) pass('addHabit() 成功');
        else warn('addHabit() 未添加（可能页面元素未就绪）');
    } catch(e) { fail('addHabit() 异常: ' + e.message); }

    try {
        showPage('placemat');
        const tInput = document.getElementById('placemat-my-input');
        if (tInput) tInput.value = '测试任务';
        const tBefore = state.myTasks.length;
        addPlacematTask('my');
        if (state.myTasks.length > tBefore) pass('addPlacematTask() 成功');
        else warn('addPlacematTask() 未添加（可能页面元素未就绪）');
    } catch(e) { fail('addPlacematTask() 异常: ' + e.message); }

    try {
        saveState();
        const saved = localStorage.getItem('cosmos_island_state_v3');
        if (saved) {
            const parsed = JSON.parse(saved);
            if (parsed.wishes && Array.isArray(parsed.wishes)) pass('saveState() 持久化成功');
            else fail('saveState() 数据格式异常');
        } else fail('saveState() 未写入 localStorage');
    } catch(e) { fail('saveState() 异常: ' + e.message); }

    
    console.log('\n--- P6: 新手指引流程 ---');
    try {
        startWelcomeTest();
        pass('startWelcomeTest() 执行成功');
    } catch(e) { fail('startWelcomeTest() 异常: ' + e.message); }

    try {
        startTutorial();
        pass('startTutorial() 执行成功');
    } catch(e) { fail('startTutorial() 异常: ' + e.message); }

    
    console.log('\n--- P7: DOM 安全性 ---');
    try {
        addVipNavEntry();
        pass('addVipNavEntry() 无 insertBefore 错误');
    } catch(e) { fail('addVipNavEntry() 异常: ' + e.message); }

    try {
        addVipToMePage();
        pass('addVipToMePage() 无 insertBefore 错误');
    } catch(e) { fail('addVipToMePage() 异常: ' + e.message); }

    
    console.log('\n========================================');
    console.log('  验证报告');
    console.log('========================================');
    console.log('通过: ' + results.passed + ' 项');
    console.log('失败: ' + results.failed + ' 项');
    console.log('警告: ' + results.warnings.length + ' 项');
    console.log('总计: ' + (results.passed + results.failed + results.warnings.length) + ' 项');
    console.log('通过率: ' + Math.round(results.passed / (results.passed + results.failed) * 100) + '%');
    if (results.failed === 0) {
        console.log('✅ 全部通过！页面运行正常。');
    } else {
        console.log('❌ 失败项：');
        results.errors.forEach((e, i) => console.log('  ' + (i+1) + '. ' + e));
    }
    if (results.warnings.length > 0) {
        console.log('⚠️ 警告项：');
        results.warnings.forEach((w, i) => console.log('  ' + (i+1) + '. ' + w));
    }
    console.log('========================================');

    window.__farmTestResults = results;
    return results;
})();


  return { results: window.__farmTestResults, logs: logs };
})();
